const files={"src/components/explorer/TopicContext.tsx": "'use client';\nimport { useEffect, useId, useState } from 'react';\nimport { usePathname } from 'next/navigation';\nimport { topics, isLanguage, type Language } from '@/lib/explorer/catalog';\nimport { prepare, presetFromSearch, type ExplorerResult } from '@/lib/explorer/prepare';\nimport { languageNames, ui } from '@/lib/explorer/locales';\nimport { ResultCard } from './ResultCard';\nexport function TopicContext(){\n const pathname=usePathname(),panelId=useId();\n const [result,setResult]=useState<ExplorerResult|null>(null),[open,setOpen]=useState(false);\n useEffect(()=>{setResult(null);setOpen(false);const topic=topics.find(t=>t.route===pathname);if(!topic)return;const q=new URLSearchParams(window.location.search);let language:Language='en';try{const l=q.get('afLang')||localStorage.getItem('afactor-simulation-language-v1');if(isLanguage(l))language=l;}catch{}\n const preset=presetFromSearch(topic.id,window.location.search);try{setResult(prepare({topicId:topic.id,language,params:preset?.params||{},modes:preset?.modes||{}}));setOpen(!!preset);}catch{}\n },[pathname]);\n if(!result||result.route!==pathname)return null;const s=ui[result.language];\n return <section aria-label={s.principle} className=\"af-explorer shrink-0 border-b border-indigo-200 bg-slate-100 px-3 py-2 text-gray-900 sm:px-4 sm:py-3\" style={{colorScheme:'light'}}><div className=\"mx-auto min-w-0 max-w-6xl\">\n  <div className=\"flex min-w-0 flex-col gap-2 md:flex-row md:items-center md:justify-between md:gap-4\">\n   <button type=\"button\" aria-expanded={open} aria-controls={panelId} onClick={()=>setOpen(v=>!v)} className=\"min-h-11 min-w-0 flex-1 rounded-lg px-1 py-2 text-left text-sm font-semibold leading-6 text-indigo-900 focus-visible:outline-2 focus-visible:outline-indigo-700\">{open?s.close:s.principle} · {result.title}<span aria-hidden=\"true\" className=\"ml-2\">{open?'▴':'▾'}</span></button>\n   <div className=\"grid min-w-0 grid-cols-[minmax(0,1fr)_minmax(0,1fr)] items-center gap-3 md:flex md:shrink-0\">\n    <select aria-label={s.language} value={result.language} onChange={e=>{const language=e.target.value as Language;setResult(prepare({topicId:result.topicId,language,params:result.params,modes:result.modes}));}} className=\"min-h-11 min-w-0 max-w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm text-gray-900\">{Object.entries(languageNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select>\n    <a href={'/explore?topic='+encodeURIComponent(result.topicId)+'&lang='+result.language} className=\"flex min-h-11 min-w-0 items-center rounded-lg py-2 text-sm leading-5 text-indigo-900 underline\">{s.review}</a>\n   </div>\n  </div>\n  <div id={panelId} hidden={!open} className=\"max-h-[min(60dvh,36rem)] min-w-0 overflow-y-auto overscroll-contain pb-1\">{open&&<ResultCard result={result} showOpen={false}/>}</div>\n </div></section>;\n}\n", "src/components/explorer/ResultCard.tsx": "'use client';\nimport { getTopic, topics } from '@/lib/explorer/catalog';\nimport { ui } from '@/lib/explorer/locales';\nimport type { ExplorerResult } from '@/lib/explorer/prepare';\nexport function ResultCard({result,showOpen=true}:{result:ExplorerResult;showOpen?:boolean}) {\n const topic=getTopic(result.topicId);if(!topic)return null;const s=ui[result.language];\n return <article lang={result.language} className=\"af-explorer mt-4 min-w-0 max-w-full rounded-2xl border border-indigo-200 bg-white p-3 sm:p-5 text-gray-900 shadow-sm\">\n  <p className=\"text-xs font-semibold text-indigo-700\">{s.free}</p><h2 className=\"mt-2 text-xl font-semibold\">{topic.title}</h2><p className=\"mt-3 text-sm leading-7\">{result.explanation}</p>\n  <div className=\"mt-4 rounded-xl bg-indigo-50 p-4\"><h3 className=\"text-xs font-semibold text-indigo-900\">{s.principle}</h3><p className=\"mt-2 text-sm leading-7 text-indigo-950\">{topic.principle}</p></div>\n  {result.calculation&&<div className=\"mt-3 rounded-xl bg-emerald-50 p-4\"><h3 className=\"text-xs font-semibold text-emerald-900\">{s.numerical}</h3><p className=\"mt-2 text-sm leading-7 text-emerald-950\">{result.calculation}</p><p className=\"mt-2 text-xs text-emerald-900\">Formulae, units and calculation assumptions: English.</p></div>}\n  {result.language!=='en'&&<details className=\"mt-3 text-sm\"><summary className=\"cursor-pointer min-h-11 py-2 text-indigo-800\">{s.source}</summary><p className=\"mt-2 leading-7\">{topic.description}</p></details>}\n  {!!topic.parameters.length&&<details className=\"mt-4 text-sm\"><summary className=\"cursor-pointer min-h-11 py-2 font-medium\">{s.settings} ({topic.parameters.length})</summary><p className=\"my-2 text-xs leading-6 text-gray-700\">{s.omitted} {s.bridge}</p><div className=\"min-w-0 max-w-full overflow-x-auto overscroll-x-contain\"><table className=\"w-full text-left text-xs\"><thead><tr className=\"border-b\"><th className=\"p-2\">Key</th><th className=\"p-2\">Value</th><th className=\"p-2\">Range</th></tr></thead><tbody>{topic.parameters.map(p=><tr className=\"border-b border-gray-100\" key={p.key}><td className=\"p-2\">{p.label} <code>({p.key})</code></td><td className=\"p-2\">{result.params[p.key]} {p.unit}{result.requested.includes(p.key)?' *':''}</td><td className=\"p-2\">{p.min}–{p.max}</td></tr>)}</tbody></table></div></details>}\n  {Object.keys(result.modes).length>0&&<p className=\"mt-3 text-xs text-gray-700\">{s.modes}: {Object.entries(result.modes).map(([k,v])=>`${k}=${v}`).join(', ')}</p>}\n  <p className=\"mt-3 text-xs leading-6 text-gray-700\">{s.manual} {s.limitations}</p>{topic.protected&&<p className=\"mt-2 text-xs font-medium text-amber-900\">{s.protected}</p>}\n  {showOpen&&<a href={result.url} className=\"mt-4 inline-flex min-h-11 w-full items-center justify-center rounded-xl bg-indigo-700 sm:w-auto px-5 py-3 text-sm font-semibold text-white hover:bg-indigo-800\">{s.open} →</a>}\n  <details className=\"mt-4 text-xs\"><summary className=\"cursor-pointer min-h-11 py-2 text-gray-700\">{s.reference}</summary><div className=\"mt-2 flex flex-wrap gap-3\">{topics.filter(t=>t.id!==topic.id&&t.concept===topic.concept).slice(0,4).map(t=><a className=\"text-indigo-800 underline\" key={t.id} href={'/explore?topic='+encodeURIComponent(t.id)+'&lang='+result.language}>{t.title}</a>)}</div></details>\n </article>;\n}\n", "src/components/explorer/explorer-mobile.css": "/* Scoped layout rules: keep the explorer inside its container without hiding overflow. */\n.af-explorer, .af-tutor { min-width: 0; max-width: 100%; }\n.af-explorer *, .af-tutor * { box-sizing: border-box; }\n.af-explorer :is(p,h1,h2,h3,h4,summary,button,a,label,code,th,td),\n.af-tutor :is(p,h1,h2,h3,h4,summary,button,a,label,code) {\n  overflow-wrap: anywhere;\n}\n.af-explorer :is(input,select,textarea), .af-tutor :is(input,select,textarea) {\n  max-width: 100%;\n}\n.af-explorer :is(section,article,fieldset,details),\n.af-tutor :is(section,article,fieldset,aside) { min-width: 0; }\n@media (max-width: 767px) {\n  /* 16px fields avoid automatic zoom on mobile Safari. */\n  .af-explorer :is(input,select,textarea), .af-tutor :is(input,select,textarea) { font-size: 16px; }\n  .af-explorer summary { line-height: 1.6; }\n  .af-explorer :is(th,td) { overflow-wrap: anywhere; }\n  .af-device > header > div { height: auto; min-height: 4rem; flex-wrap: wrap; gap: .75rem; padding-block: .75rem; }\n  .af-device > header > div > div { min-width: 0; max-width: 100%; flex-wrap: wrap; gap: .5rem; }\n  .af-device > header h1 { font-size: 1rem; line-height: 1.5; overflow-wrap: anywhere; }\n  .af-device > main { padding: .75rem; }\n}\n", "src/components/ai/PromptBar.tsx": "'use client';\nimport { useEffect, useRef, useState } from 'react';\nimport type { AIPromptResponse } from '@/types/ai';\nimport { getTopic, isLanguage, topics, type Language } from '@/lib/explorer/catalog';\nimport { languageNames, ui } from '@/lib/explorer/locales';\nimport type { ExplorerResult } from '@/lib/explorer/prepare';\nimport { ResultCard } from '@/components/explorer/ResultCard';\ninterface Props { onResult?:(result:AIPromptResponse)=>void; className?:string; }\nexport function PromptBar({onResult,className}:Props) {\n const [language,setLanguage]=useState<Language>('en'),[topicId,setTopicId]=useState(''),[prompt,setPrompt]=useState('');\n const [numbers,setNumbers]=useState<Record<string,string>>({}),[modes,setModes]=useState<Record<string,string>>({});\n const [result,setResult]=useState<ExplorerResult|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);\n const pending=useRef<AbortController|null>(null);const s=ui[language],topic=getTopic(topicId);\n useEffect(()=>{const q=new URLSearchParams(window.location.search),id=q.get('topic'),lang=q.get('lang');if(id&&getTopic(id))setTopicId(id);try{const saved=lang||localStorage.getItem('afactor-simulation-language-v1');if(isLanguage(saved))setLanguage(saved);}catch{}return()=>pending.current?.abort();},[]);\n function reset(){pending.current?.abort();pending.current=null;setBusy(false);setError('');setResult(null);}\n function changeTopic(id:string){reset();setTopicId(id);setNumbers({});setModes({});}\n function changeLanguage(value:Language){reset();setLanguage(value);try{localStorage.setItem('afactor-simulation-language-v1',value);}catch{}}\n async function submit(text=prompt){if(busy||(!text.trim()&&!topicId))return;const controller=new AbortController();pending.current=controller;setBusy(true);setError('');setResult(null);const timer=setTimeout(()=>controller.abort(),15000);\n try {const params:Record<string,number>={};for(const [k,v] of Object.entries(numbers))if(v.trim())params[k]=Number(v);const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({prompt:text,topicId:topicId||undefined,language,params,modes})});const data=await r.json();if(!r.ok)throw Error(data.error||s.error);if(pending.current!==controller)return;setResult(data);\n // Preserve the homepage's existing projectile preview for the compatible standard case.\n if(onResult&&window.location.pathname==='/'&&data.topicId==='simulations-projectile-motion'&&data.modes.mode==='standard'&&data.params.h0===0)onResult({simulationType:'projectile_motion',title:data.title,description:data.explanation,explanation:data.explanation,params:{initialVelocity:data.params.v0,angle:data.params.angle,gravity:data.params.g,mass:1},suggestedFollowUps:[]});\n }catch(e){if(pending.current===controller)setError(e instanceof Error?e.message:s.error);}finally{clearTimeout(timer);if(pending.current===controller){pending.current=null;setBusy(false);}}}\n const sample=topic?`${topic.title}${topic.parameters.length?' '+topic.parameters[0].key+'='+topic.parameters[0].default:''}`:'';\n return <div className={`af-explorer min-w-0 max-w-full ${className || ''}`} style={{colorScheme:'light'}}><div className=\"grid gap-3 md:grid-cols-[minmax(0,1fr)_180px]\">\n  <label className=\"min-w-0 text-xs font-semibold text-gray-800\">{s.topic}<select value={topicId} onChange={e=>changeTopic(e.target.value)} className=\"mt-1 min-h-11 min-w-0 max-w-full w-full rounded-xl border border-gray-300 bg-white p-3 text-sm text-gray-900\"><option value=\"\">{s.automatic}</option>{['Physics','Chemistry','Mathematics','Geophysics'].map(subject=><optgroup label={subject} key={subject}>{topics.filter(t=>t.subject===subject).map(t=><option key={t.id} value={t.id}>{t.title}</option>)}</optgroup>)}</select></label>\n  <label className=\"min-w-0 text-xs font-semibold text-gray-800\">{s.language}<select value={language} onChange={e=>changeLanguage(e.target.value as Language)} className=\"mt-1 min-h-11 min-w-0 max-w-full w-full rounded-xl border border-gray-300 bg-white p-3 text-sm text-gray-900\">{Object.entries(languageNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>\n </div><p className=\"my-3 text-xs leading-6 text-emerald-900\">{s.free}</p><form onSubmit={e=>{e.preventDefault();void submit();}} className=\"flex flex-col gap-2 sm:flex-row\"><label className=\"sr-only\" htmlFor=\"all-topic-prompt\">{s.prompt}</label><input id=\"all-topic-prompt\" value={prompt} maxLength={1200} onChange={e=>setPrompt(e.target.value)} placeholder={s.prompt} className=\"min-h-11 min-w-0 flex-1 rounded-xl border border-gray-300 bg-white px-4 py-3 text-sm text-gray-900 placeholder:text-gray-600\" /><button disabled={busy||(!prompt.trim()&&!topicId)} className=\"min-h-11 rounded-xl bg-indigo-700 px-5 py-3 text-sm font-semibold text-white disabled:opacity-50\">{busy?'…':s.apply}</button></form>\n {topic&&<details className=\"mt-3 rounded-xl border border-gray-200 bg-white p-4\"><summary className=\"min-h-11 cursor-pointer py-2 text-sm font-medium text-gray-800\">{s.settings} · {topic.parameters.length}</summary><p className=\"my-3 text-xs leading-6 text-gray-700\">{s.omitted} {s.manual}</p><div className=\"grid gap-3 sm:grid-cols-2 lg:grid-cols-3\">{topic.modes.map(m=><label key={m.key} className=\"min-w-0 text-xs text-gray-800\">{s.modes}: {m.key}<select value={modes[m.key]||m.default} onChange={e=>{setResult(null);setModes(old=>({...old,[m.key]:e.target.value}));}} className=\"mt-1 min-h-11 min-w-0 max-w-full w-full rounded-lg border border-gray-300 bg-white p-2\">{m.options.map(v=><option key={v}>{v}</option>)}</select></label>)}{topic.parameters.map(p=><label key={p.key} className=\"min-w-0 text-xs text-gray-800\">{p.label} <code>({p.key})</code><input type=\"number\" step=\"any\" min={p.min} max={p.max} value={numbers[p.key]??''} placeholder={String(p.default)} onChange={e=>{setResult(null);setNumbers(old=>({...old,[p.key]:e.target.value}));}} className=\"mt-1 min-h-11 min-w-0 max-w-full w-full rounded-lg border border-gray-300 bg-white p-2 text-gray-900\" /><span className=\"mt-1 block text-gray-600\">{p.min}–{p.max} {p.unit}</span></label>)}</div></details>}\n <div className=\"mt-3 flex flex-wrap gap-2\">{(topic?[sample]:['Ohm 12 V 6 ohm',\"Newton second law 10 kg 50 N friction2=0\",'Waves f=1 lambda=2','Projectile 30 m/s 45°']).map(text=><button key={text} onClick={()=>{setPrompt(text);void submit(text);}} disabled={busy} className=\"min-h-11 max-w-full rounded-xl border border-gray-300 bg-white px-3 py-2 text-left text-xs leading-5 text-gray-800\">{text}</button>)}</div>\n {error&&<p role=\"alert\" className=\"mt-3 rounded-xl bg-red-50 p-3 text-sm text-red-900\">{error}</p>}{result&&<ResultCard result={result}/>}<p className=\"mt-4 text-xs leading-6 text-gray-600\">{s.notes}</p></div>;\n}\n", "src/app/explore/page.tsx": "import { AppHeader } from '@/components/layout/AppHeader';\nimport { PromptBar } from '@/components/ai/PromptBar';\nimport { topics } from '@/lib/explorer/catalog';\nexport const metadata={title:'Topic explorer | A-Factor STEM Studio'};\nexport default function ExplorePage(){return <div style={{background:'#f1f5f9',minHeight:'100vh',color:'#111827',colorScheme:'light'}}><AppHeader/><main className=\"af-explorer mx-auto min-w-0 max-w-6xl px-3 py-6 sm:px-6 sm:py-10\"><p className=\"text-xs font-semibold uppercase tracking-widest text-indigo-700\">A-Factor STEM Studio</p><h1 className=\"mt-2 text-3xl font-semibold\">Explore all {topics.length} topics</h1><p className=\"mb-7 mt-3 max-w-2xl text-sm leading-7 text-gray-700\">Physics, Chemistry, Mathematics and Geophysics. Select an existing activity, prepare supported controls, and read a topic-specific explanation without a paid AI API.</p><PromptBar/></main></div>;}\n", "capstone/EXPLORER_MOBILE_FIX.md": "# Header placement and mobile layout fix\n\nRun from the existing project root after the all-topic explorer patch:\n\n```bash\nbash patch-explorer-mobile-layout.sh\nnpm run dev\n```\n\nRefresh the page. The explainer now belongs immediately after the shared AppHeader, rather than before the page in RootLayout. BJT and PN-junction pages receive it after their own custom headers. Geophysics inherits the corrected position through its existing AppHeader. The root layout only loads scoped responsive styles. This prevents duplicate explanation panels.\n\nResponsive adjustments cover the new explorer, topic explainer, tutor, shared navigation and the two custom device-page headers:\n\n- Tablet navigation stays in the mobile menu until the large-screen breakpoint.\n- Mobile menus scroll independently when taller than the viewport.\n- Explainer controls stack on narrow screens and have 44px minimum targets.\n- Expanded explanations have a bounded scrolling area, keeping the header reachable.\n- Long topic names, local-language text, formulae and parameter keys wrap.\n- Parameter tables scroll within their card, rather than widening the whole page.\n- Mobile form controls use 16px text to avoid automatic Safari zoom.\n- The shared navigation menu and explainer disclose their expanded state to assistive technology.\n\nThe script backs up changed files and preserves unrelated layout/header edits. It does not change physics models, parameters, authentication, API credentials or the catalogue. Existing simulation-specific controls and canvases keep their own responsive implementation; this patch is not a redesign of every original activity.\n\nTypeScript and production build checks were run. Installer checks cover initial application, repeat runs and header/explainer ordering. Physical-device and interactive browser checks remain unverified because the managed preview launcher is incompatible with this project's Next.js dev flags.\n\nAfter applying, check /explore and an opened simulation at phone portrait/landscape and tablet widths. The main header should precede the explanation panel, controls should fit the available width, and a long parameter table should scroll inside its card.\n"};
function stop(message){console.error('Patch stopped: '+message+' No application files changed.');process.exit(1);}
if(!fs.existsSync('package.json')||!fs.existsSync('src/lib/explorer/catalog.ts'))stop('Run from your project root after installing the all-topic explorer patch.');
let ts;try{ts=require(path.join(root,'node_modules/typescript'));}catch{stop('Run npm install for your existing dependencies first.');}
function safe(file){let cur=root;for(const part of file.split('/')){cur=path.join(cur,part);try{if(fs.lstatSync(cur).isSymbolicLink())stop('Symbolic link at '+file);}catch(e){if(e.code!=='ENOENT')throw e;}}}
function read(file){safe(file);if(!fs.existsSync(file))stop('Missing '+file);return fs.readFileSync(file,'utf8');}
function ast(file,src){return ts.createSourceFile(file,src,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);}
function walk(n,fn){fn(n);ts.forEachChild(n,c=>walk(c,fn));}
function addImport(file,src,line,module){if(src.includes("from '"+module+"'"))return src;const first=ast(file,src).statements[0];const at=first&&ts.isExpressionStatement(first)&&ts.isStringLiteral(first.expression)?first.end:0;return src.slice(0,at)+'\n'+line+'\n'+src.slice(at);}
function headerNode(file,src){const found=[];walk(ast(file,src),n=>{if(ts.isJsxElement(n)&&n.openingElement.tagName.getText()==='header')found.push(n);});if(found.length!==1)stop('Cannot locate a unique header in '+file);return found[0];}
const layout='src/app/layout.tsx';let l=read(layout);
l=l.replace(/import\s*\{\s*TopicContext\s*\}\s*from\s*['"]@\/components\/explorer\/TopicContext['"];?\r?\n?/g,'').replace(/<TopicContext\s*\/>/g,'');
if(!l.includes("@/components/explorer/explorer-mobile.css"))l="import '@/components/explorer/explorer-mobile.css';\n"+l;files[layout]=l;
const header='src/components/layout/AppHeader.tsx';let h=read(header);
let tree=ast(header,h),reactImport=tree.statements.find(n=>ts.isImportDeclaration(n)&&n.moduleSpecifier.text==='react');
const bindings=reactImport?.importClause?.namedBindings;if(!bindings||!ts.isNamedImports(bindings))stop('Could not locate React hooks in the shared header.');
const names=bindings.elements.map(n=>n.getText());for(const name of ['useEffect','useId'])if(!names.includes(name))names.push(name);
h=h.slice(0,bindings.getStart())+'{ '+names.join(', ')+' }'+h.slice(bindings.end);
if(!h.includes('const menuId = useId();')){const marker='const pathname = usePathname();';if(!h.includes(marker))stop('Could not locate the shared header pathname.');h=h.replace(marker,marker+'\n  const menuId = useId();\n  useEffect(() => { setOpen(false); }, [pathname]);');}
if(!h.includes('<TopicContext')){const node=headerNode(header,h);h=h.slice(0,node.getStart())+'<>'+h.slice(node.getStart(),node.end)+'<TopicContext /></>'+h.slice(node.end);}
h=addImport(header,h,"import { TopicContext } from '@/components/explorer/TopicContext';",'@/components/explorer/TopicContext');
h=h.replace('hidden sm:flex items-center gap-1','hidden lg:flex items-center gap-1')
 .replace('sm:hidden rounded-lg p-2','lg:hidden flex min-h-11 min-w-11 items-center justify-center rounded-lg p-2')
 .replace('sm:hidden border-t border-gray-100 py-3 space-y-1','lg:hidden max-h-[calc(100dvh-3.5rem)] overflow-y-auto overscroll-contain border-t border-gray-100 py-3 space-y-1')
 .replace('className="flex items-center gap-2 group"','className="flex shrink-0 items-center gap-2 group"');
if(!h.includes('aria-controls={menuId}'))h=h.replace('aria-label="Menu"','aria-label="Menu" aria-expanded={open} aria-controls={menuId}');
h=h.replace('<div className="lg:hidden max-h','<div id={menuId} className="lg:hidden max-h').split('block px-3 py-2 rounded-lg').join('block px-3 py-3 rounded-lg');files[header]=h;
for(const file of ['src/app/simulations/pn-junction/page.tsx','src/app/simulations/bjt-transistor/page.tsx']){let s=read(file);if(!s.includes('<TopicContext')){const node=headerNode(file,s);s=s.slice(0,node.end)+'\n      <TopicContext />'+s.slice(node.end);}s=addImport(file,s,"import { TopicContext } from '@/components/explorer/TopicContext';",'@/components/explorer/TopicContext');s=s.replace('className="min-h-screen bg-slate-950','className="af-device min-h-screen bg-slate-950');files[file]=s;}
const tutor='src/app/tutor/page.tsx';if(fs.existsSync(tutor)){const s=read(tutor);if(!s.includes('className="af-tutor"'))files[tutor]=s.replace('<div data-stem-tutor-contrast','<div className="af-tutor" data-stem-tutor-contrast');}
for(const file of [...Object.keys(files),'.stem-tutor-backups'])safe(file);
const changed=Object.keys(files).filter(file=>!fs.existsSync(file)||fs.readFileSync(file,'utf8')!==files[file]);if(!changed.length){console.log('Header placement and mobile-layout fix already installed.');process.exit(0);}
fs.mkdirSync('.stem-tutor-backups',{recursive:true});const backup=fs.mkdtempSync('.stem-tutor-backups/mobile-layout-'),originals=new Map();
for(const file of changed){const original=fs.existsSync(file)?fs.readFileSync(file):null;originals.set(file,original);if(original!==null){const target=path.join(backup,file);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,original);}}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify(changed.map(file=>({file,existed:originals.get(file)!==null})),null,2));
try{for(const file of changed){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,files[file],'utf8');}}catch(error){for(const [file,original] of originals){if(original===null){if(fs.existsSync(file))fs.unlinkSync(file);}else fs.writeFileSync(file,original);}console.error('Write failed; originals restored: '+error.message);process.exit(1);}
console.log('Explainer moved below the header. Mobile explorer/navigation layout updated.');console.log('Backup: '+backup);console.log('Restart npm run dev, then refresh /explore or a simulation.');
